typedef struct {
    uint32_t name_index;   // String table offset
    uint8_t  type_binding; // STT_FUNC, STT_OBJECT, STB_GLOBAL, STB_WEAK
    uint16_t section_idx;  // SHN_UNDEF (reference) or defined section
    uintptr_t value;       // Address relative to section start
    uintptr_t size;        // Size of object/function
} SymEntry; // Symbol Table Entry (Resolution Source)

typedef struct {
    uintptr_t offset;      // Location (address) to patch
    uint32_t info;         // (sym_index << 8) | type (R_X86_64_PC32)
} RelocEntry; // Relocation Table Entry (Fixup Instruction)

// Process:
// 1. Find target symbol in SymEntry via info->sym_index.
// 2. Calculate needed address 'A'.
// 3. Patch code at RelocEntry->offset with 'A'.
